// HMAC-SHA256 over "<timestamp>.<rawBody>", same scheme as convex/lib/signature.ts.
// The secret comes from the n8n container environment, never from this workflow.
const crypto = require('crypto');
function sign(bodyObject) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment');
  const body = JSON.stringify(bodyObject);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, signature, timestamp };
}

// The Error Trigger receives { execution, workflow }. We forward only operational data, no payloads/PII.
const { execution = {}, workflow = {} } = $input.first().json;
const failure = {
  workflowName: String(workflow.name || 'unknown workflow').slice(0, 200),
  executionId: String(execution.id || 'trigger-' + Date.now()).slice(0, 64),
  lastNode: execution.lastNodeExecuted ? String(execution.lastNodeExecuted).slice(0, 200) : undefined,
  message: String((execution.error && execution.error.message) || 'Unknown error').slice(0, 1000),
};
// Always visible in the n8n container logs, even if Convex is unreachable.
console.error('[lendloop-error-workflow]', JSON.stringify(failure));
return [{ json: { ...sign(failure), failure } }];

const f = $('Build failure report').first().json.failure;
const to = $env.LENDLOOP_ALERT_EMAIL;
if (!to) return [];
return [{ json: { to, subject: '[LendLoop] Workflow failed: ' + f.workflowName,
  text: 'Workflow: ' + f.workflowName + '\nExecution: ' + f.executionId + '\nLast node: ' + (f.lastNode || '-') + '\nError: ' + f.message } }];
